const clock = new THREE.Clock();

renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

scene.background = new THREE.Color(0xf4f7fb);
scene.fog = new THREE.Fog(0xf4f7fb, 8, 25);

const keyLight = new THREE.DirectionalLight(0xfff8f0, 1.4);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 50;
keyLight.shadow.bias = -0.0005;

const fillLight = new THREE.DirectionalLight(0xddeeff, 0.6);
fillLight.position.set(-8, 5, 6);

const rimLight = new THREE.SpotLight(0xaaddff, 0.8);
rimLight.position.set(-5, 8, -8);
rimLight.lookAt(0, 0, 0);

scene.add(new THREE.AmbientLight(0x7f8aa6, 0.35), keyLight, fillLight, rimLight);

const floorGeo = new THREE.CircleGeometry(12, 128);
const floorMat = new THREE.MeshStandardMaterial({ 
  color: 0xe8eef5, 
  roughness: 0.85, 
  metalness: 0.05 
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1.2;
floor.receiveShadow = true;
scene.add(floor);

const podiumGeo = new THREE.CylinderGeometry(1.5, 1.7, 0.4, 64);
const podiumMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  roughness: 0.2,
  metalness: 0.1,
  clearcoat: 0.3,
  clearcoatRoughness: 0.1
});
const podium = new THREE.Mesh(podiumGeo, podiumMat);
podium.position.y = -1.0;
podium.receiveShadow = true;
podium.castShadow = true;
scene.add(podium);

const heroGroup = new THREE.Group();
scene.add(heroGroup);

const particleCount = 40;
const particleGeo = new THREE.SphereGeometry(0.04, 16, 16);
const particleMat = new THREE.MeshPhysicalMaterial({
  color: 0xaaddff,
  metalness: 0.1,
  roughness: 0.1,
  transmission: 0.6,
  transparent: true,
  opacity: 0.8
});
const particles = new THREE.InstancedMesh(particleGeo, particleMat, particleCount);
const dummy = new THREE.Object3D();
const particleData = [];

for (let i = 0; i < particleCount; i++) {
  const angle = (i / particleCount) * Math.PI * 2;
  const radius = 3 + Math.random() * 2;
  const y = Math.random() * 4;
  dummy.position.set(Math.cos(angle) * radius, y, Math.sin(angle) * radius);
  dummy.updateMatrix();
  particles.setMatrixAt(i, dummy.matrix);
  particleData.push({
    angle: angle,
    radius: radius,
    yBase: y,
    speed: 0.2 + Math.random() * 0.4,
    offset: Math.random() * Math.PI * 2
  });
}
scene.add(particles);

const loader = new THREE.GLTFLoader();
let mixer;

loader.load(
  'https://rawcdn.githack.com/mrdoob/three.js/r128/examples/models/gltf/Fox.glb',
  (gltf) => {
    const model = gltf.scene;
    model.scale.set(0.025, 0.025, 0.025);
    model.position.set(0, -1.0, 0);

    model.traverse((child) => {
      if (child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
        if (child.material) {
          child.material.roughness = Math.min(child.material.roughness, 0.8);
        }
      }
    });

    heroGroup.add(model);

    if (gltf.animations.length > 0) {
      mixer = new THREE.AnimationMixer(model);
      const action = mixer.clipAction(gltf.animations[0]);
      action.setEffectiveTimeScale(0.8);
      action.play();
    }
  },
  undefined,
  (error) => {
    console.warn('Curated asset load failed, using procedural fallback');
    const fallbackGeo = new THREE.IcosahedronGeometry(0.8, 3);
    const fallbackMat = new THREE.MeshStandardMaterial({ 
      color: 0xff5533, 
      roughness: 0.6 
    });
    const fallback = new THREE.Mesh(fallbackGeo, fallbackMat);
    fallback.position.y = 0.3;
    fallback.castShadow = true;
    heroGroup.add(fallback);
  }
);

camera.position.set(4.5, 2.8, 6.0);
camera.lookAt(0, 0.5, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.maxPolarAngle = Math.PI / 2 - 0.05;
