function animate() {
  requestAnimationFrame(animate);

  const dt = clock.getDelta();
  const t = clock.getElapsedTime();

  if (mixer) mixer.update(dt);

  heroGroup.rotation.y = Math.sin(t * 0.3) * 0.15;

  rimLight.intensity = 0.6 + Math.sin(t * 1.5) * 0.15;

  for (let i = 0; i < particleCount; i++) {
    const data = particleData[i];
    const angle = data.angle + t * data.speed * 0.2;
    const y = data.yBase + Math.sin(t * data.speed + data.offset) * 0.3;
    dummy.position.set(
