      y,
      Math.sin(angle) * data.radius
    );
    dummy.scale.setScalar(0.8 + Math.sin(t * 2 + data.offset) * 0.2);
    dummy.updateMatrix();
    particles.setMatrixAt(i, dummy.matrix);
